export interface Sample {
  table: string
  file: string
  title: string
  description: string
  format: 'Parquet' | 'CSV' | 'JSON'
  rows: string
  query: string
}

/** Bundled datasets (synthetic, generated by scripts/generate_samples.py). */
export const SAMPLES: Sample[] = [
  {
    table: 'taxi_trips',
    file: 'taxi_trips.parquet',
    title: 'NYC-style taxi trips',
    description: 'Pickups, distances, fares and tips with GPS-glitch outliers and missing passenger counts.',
    format: 'Parquet',
    rows: '60k',
    query: `-- Busiest pickup boroughs and what riders pay there
SELECT
  pickup_borough,
  count(*)                         AS trips,
  round(avg(trip_miles), 2)        AS avg_miles,
  round(median(fare_usd), 2)       AS median_fare,
  round(sum(tip_usd) / sum(fare_usd) * 100, 1) AS tip_pct
FROM taxi_trips
GROUP BY ALL
ORDER BY trips DESC;`,
  },
  {
    table: 'ecommerce_orders',
    file: 'ecommerce_orders.csv',
    title: 'E-commerce orders',
    description: 'Two years of orders by country, channel and category — with duplicates, a constant column and a mixed-type rating.',
    format: 'CSV',
    rows: '15k',
    query: `-- Monthly revenue by category (delivered orders)
SELECT
  date_trunc('month', order_date) AS month,
  category,
  round(sum(revenue), 2)          AS revenue,
  count(DISTINCT customer_id)     AS customers
FROM ecommerce_orders
WHERE status = 'delivered'
GROUP BY ALL
ORDER BY month, revenue DESC;`,
  },
  {
    table: 'daily_metrics',
    file: 'daily_metrics.json',
    title: 'Daily product metrics',
    description: 'Sessions, signups, orders and revenue per region per day — trend, weekly seasonality and a campaign spike.',
    format: 'JSON',
    rows: '2.2k',
    query: `-- 7-day rolling conversion rate per region
SELECT
  date,
  region,
  orders / sessions AS conversion,
  avg(orders / sessions) OVER (
    PARTITION BY region ORDER BY date ROWS BETWEEN 6 PRECEDING AND CURRENT ROW
  ) AS conversion_7d
FROM daily_metrics
ORDER BY region, date;`,
  },
]

export const DEFAULT_SQL = SAMPLES[0].query

export function sampleUrl(s: Sample): string {
  return `${import.meta.env.BASE_URL}samples/${s.file}`
}
